mapper.select:
SELECT  FROM ifj_notification_outbox o LEFT JOIN ifj_notify_config c ON c.id = o.notify_config_id
WHERE o.create_time >= #{fromTime} AND o.create_time <= #{toTime}

    AND o.status = 'RETRY_WAIT' AND o.last_failure_code = 'RATE_WAIT'
    AND o.status = #{deliveryStatus}

AND o.notify_config_id = #{notifyConfigId}
AND o.instance_id = #{instanceId}
AND o.source_type = #{sourceType}
AND o.target_type = #{targetType} AND o.target_id = #{targetId}
ORDER BY o.create_time DESC, o.id DESC
